-- Db2-specific trailing clauses for CREATE TABLE.
-- https://www.ibm.com/docs/en/db2/11.5?topic=statements-create-table

CREATE TABLE t (a INT) ORGANIZE BY ROW;

CREATE TABLE t (a INT) ORGANIZE BY ROW USING (a);

CREATE TABLE t (a INT) ORGANIZE BY ROW USING DIMENSIONS (a);

CREATE TABLE t (a INT) ORGANIZE BY ROW USING INSERT TIME;

CREATE TABLE t (a INT) ORGANIZE BY ROW DIMENSIONS (a);

CREATE TABLE t (a INT, b INT) ORGANIZE BY ROW USING (a, (b, a));

CREATE TABLE t (a INT) ORGANIZE BY DIMENSIONS (a);

CREATE TABLE t (a INT)
ORGANIZE BY ROW
KEY SEQUENCE (a STARTING FROM 1 ENDING AT 100)
DISALLOW OVERFLOW
PCTFREE 10;

CREATE TABLE t (a INT) ORGANIZE BY KEY SEQUENCE (a) ALLOW OVERFLOW;

CREATE TABLE t (a INT) ORGANIZE BY ROW INSERT TIME;

CREATE TABLE t (a INT) ORGANIZE BY INSERT TIME;

CREATE TABLE t (a INT) ORGANIZE BY COLUMN;

CREATE TABLE t (a INT) DISTRIBUTE BY HASH (a);

CREATE TABLE t (a INT) DISTRIBUTE BY RANDOM;

CREATE TABLE t (a INT) DISTRIBUTE BY REPLICATION;

CREATE TABLE t (a INT) IN ts;

CREATE TABLE t (a INT) IN ts INDEX IN ts2;

CREATE TABLE t (a INT) IN ts INDEX IN ts2 LONG IN ts3;

CREATE TABLE t (a INT) IN ts CYCLE;

CREATE TABLE t (a INT) IN ts NO CYCLE;

CREATE TABLE t (a INT) WITH RESTRICT ON DROP;

CREATE TABLE t (a INT)
ORGANIZE BY ROW
DISTRIBUTE BY HASH (a)
IN ts INDEX IN ts2 LONG IN ts3
WITH RESTRICT ON DROP;
